import AppKit
import DevBarCore
import ImageIO
import UniformTypeIdentifiers

struct PasteboardMetadata: Sendable {
  enum Access: Sendable { case allow, ask, deny }
  let count: Int
  let types: [String]
  let access: Access

  var concealed: Bool {
    types.contains {
      [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
      ].contains($0)
    }
  }
}

protocol PasteboardReading: Sendable {
  func metadata() -> PasteboardMetadata
  func read() -> [ClipboardPayload]
}

/// Holds a name, not a cross-thread AppKit object. Content reads run on a worker.
struct SystemPasteboardReader: PasteboardReading {
  let name: NSPasteboard.Name
  init(name: NSPasteboard.Name = .general) { self.name = name }

  func metadata() -> PasteboardMetadata {
    let board = NSPasteboard(name: name)
    let access: PasteboardMetadata.Access
    switch board.accessBehavior {
    case .alwaysAllow: access = .allow
    case .alwaysDeny: access = .deny
    default: access = .ask
    }
    return PasteboardMetadata(
      count: board.changeCount,
      types: (board.types ?? []).map(\.rawValue), access: access)
  }

  static let imageTypes: [NSPasteboard.PasteboardType] = [
    .png, .tiff, .init(UTType.jpeg.identifier), .init(UTType.heic.identifier),
    .init(UTType.webP.identifier),
  ]

  func read() -> [ClipboardPayload] {
    let board = NSPasteboard(name: name)
    let items = board.pasteboardItems ?? []
    let files = items.compactMap { item -> ClipboardPayload? in
      guard item.types.contains(.fileURL), let data = item.data(forType: .fileURL), !data.isEmpty
      else { return nil }
      return ClipboardPayload(type: NSPasteboard.PasteboardType.fileURL.rawValue, data: data)
    }
    if !files.isEmpty { return files }
    let imageTypes = Self.imageTypes
    let types: [NSPasteboard.PasteboardType] =
      imageTypes.contains(where: { board.types?.contains($0) == true })
      ? imageTypes : [.string, .rtf, .html]
    var payloads: [ClipboardPayload] = []
    for type in types {
      // PNG is tried first, so its presence makes the TIFF fallback unnecessary.
      if type == .tiff && payloads.first?.type == NSPasteboard.PasteboardType.png.rawValue {
        continue
      }
      guard board.types?.contains(type) == true, let data = board.data(forType: type), !data.isEmpty
      else { continue }
      payloads.append(ClipboardPayload(type: type.rawValue, data: data))
    }
    return payloads
  }
}

struct ClipboardCapture: Sendable {
  let kind: ClipItem.Kind
  let preview: String
  let payloads: [ClipboardPayload]
  let thumbnail: Data?

  init?(payloads: [ClipboardPayload]) {
    guard !payloads.isEmpty else { return nil }
    if payloads.contains(where: { $0.type == NSPasteboard.PasteboardType.fileURL.rawValue }) {
      let urls = payloads.filter { $0.type == NSPasteboard.PasteboardType.fileURL.rawValue }
        .compactMap { String(data: $0.data, encoding: .utf8) }.compactMap(URL.init(string:))
      if urls.count == 1, let url = urls.first, url.isFileURL, !url.hasDirectoryPath,
        let fileType = UTType(filenameExtension: url.pathExtension), fileType.conforms(to: .image),
        let fileSize = (try? url.resourceValues(forKeys: [.fileSizeKey]).fileSize),
        fileSize > 0, fileSize <= ClipboardStore.imageByteLimit,
        let imageData = try? Data(contentsOf: url),
        !imageData.isEmpty, imageData.count <= ClipboardStore.imageByteLimit,
        let source = CGImageSourceCreateWithData(imageData as CFData, nil),
        let thumb = Self.thumbnail(source)
      {
        let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any]
        let width = properties?[kCGImagePropertyPixelWidth] as? Int ?? 0
        let height = properties?[kCGImagePropertyPixelHeight] as? Int ?? 0
        kind = .image
        preview = width > 0 && height > 0 ? "\(width) × \(height)" : url.lastPathComponent
        thumbnail = thumb
        self.payloads = [ClipboardPayload(type: fileType.identifier, data: imageData)] + payloads
        return
      }
      kind = .files
      preview = urls.map(\.lastPathComponent).joined(separator: ", ")
      thumbnail = nil
      self.payloads = payloads
    } else if let image = payloads.first(where: {
      SystemPasteboardReader.imageTypes.map(\.rawValue).contains($0.type)
    }) {
      self.payloads = payloads
      kind = .image
      if let source = CGImageSourceCreateWithData(image.data as CFData, nil) {
        let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any]
        let width = properties?[kCGImagePropertyPixelWidth] as? Int ?? 0
        let height = properties?[kCGImagePropertyPixelHeight] as? Int ?? 0
        preview = "\(width) × \(height)"
        thumbnail = Self.thumbnail(source)
      } else {
        preview = Strings.clipboardImage
        thumbnail = nil
      }
    } else {
      self.payloads = payloads
      kind = .text
      preview =
        payloads.first(where: { $0.type == NSPasteboard.PasteboardType.string.rawValue })
        .flatMap { String(data: $0.data, encoding: .utf8) } ?? Strings.clipboardRichText
      thumbnail = nil
    }
  }

  init?(screenshotPNG: Data, file: URL) {
    guard
      let capture = ClipboardCapture(payloads: [
        ClipboardPayload(type: NSPasteboard.PasteboardType.png.rawValue, data: screenshotPNG)
      ])
    else { return nil }
    kind = .image
    preview = capture.preview
    thumbnail = capture.thumbnail
    payloads =
      capture.payloads + [
        ClipboardPayload(
          type: NSPasteboard.PasteboardType.fileURL.rawValue, data: Data(file.absoluteString.utf8))
      ]
  }

  private static func thumbnail(_ source: CGImageSource) -> Data? {
    guard
      let image = CGImageSourceCreateThumbnailAtIndex(
        source, 0,
        [
          kCGImageSourceCreateThumbnailFromImageAlways: true,
          kCGImageSourceThumbnailMaxPixelSize: 320,
          kCGImageSourceCreateThumbnailWithTransform: true,
        ] as CFDictionary)
    else { return nil }
    let data = NSMutableData()
    guard
      let destination = CGImageDestinationCreateWithData(
        data, UTType.png.identifier as CFString, 1, nil)
    else { return nil }
    CGImageDestinationAddImage(destination, image, nil)
    return CGImageDestinationFinalize(destination) ? data as Data : nil
  }
}
